            goal: 'At omstille 60% af sin flåde til oppustelige soft-top SUP-brætter, der matcher performance fra 9\'0" hardboards, holder mindst 36 måneder under hård kommerciel brug og reducerer de årlige vedligeholdelsesomkostninger med mindst 60% inden for 12 måneder.',
