            background:
              'Noosa Outdoor School, en dedikeret udendørsuddannelsesfacilitet der betjener 6 grundskoler i Sunshine Coast-regionen, afvikler 80+ programmer årligt til 2.100 elever i alderen 5-12 år. Leder af udendørsprogrammer Liam Connolly, en tidligere surfinstruktør ved AIS, konstaterede, at deres vandbaserede programmer udelukkende brugte kajakker (32 sit-on-top-kajakker), hvilket begrænsede engagementet for mindre og mindre selv sikre elever, der oplevede kajakkerne som ustabile. En pilot i 2024 med 4 voksen-SUP-brætter viste 92% elevengagement mod 67% for kajakker, men brættene var for høje (6" tykke) for 5-7-årige og krævede voksen hjælp til at stige om bord. Connolly havde brug for en dedikeret børne-SUP-platform med et integreret udforskningspensum.',
