                'Flåden på 60 brætter blev udrullet på 4 skibe fra 1. juni 2024. Hvert skib tilbød 3 padlesessioner om ugen (vejrafhængige, 90 minutter hver). Samlede sessioner i sæsonen 2024: 288 sessioner på tværs af alle skibe (4 skibe × 3/uge × 24 uger). Gennemsnitlig belægning: 7,2 gæster pr. session (90% af kapaciteten på 8 gæster). Omsætning: 288 × 7,2 × $450 (premium-udflugtspris) = $933.120. Brætperformance: nul katastrofale fejl. Ét bræt fik en 3 cm punktering fra havis (en skarp brash-issplint) — repareret med arktisk reparationskit på 8 minutter under en Zodiac-drift. Ventilerne fungerede upåklageligt over 288 oppustnings-/tømningscyklusser. Gæstefeedback: 4,93/5 i gennemsnit. 83% af gæsterne sagde, at SUP-oplevelsen var »højdepunktet på deres rejse«. Erik bestilte 40 ekstra brætter til sæsonen 2025 og bad Afarer udvikle en »Twin«-model til tandem-padling i Arktis.',
