            'Flådetilgængeligheden steg til 98,5%, hvilket gjorde det muligt for Mara at acceptere 23 ekstra turbestillinger i højsæsonen',
            'Kundetilfredshedsscorer i turanmeldelser forbedredes fra 4,1 til 4,8 ud af 5 og blev direkte tilskrevet »bedre udstyrskvalitet«',
